## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/amyloidosisLogic.ts`

```typescript
// ─────────────────────────────────────────────────────────────────────────────
// Amyloidosis Diagnostic & Decision Support Logic Engine
// Sources:
//   Gertz MA et al. ASH 2020 — Systemic Amyloidosis Diagnosis & Treatment
//   Gillmore JD et al. Lancet 2022 — ATTR-CM Diagnosis (PMID 35240070)
//   Garcia-Pavia P et al. Eur Heart J 2021 — ATTR-CM Guidelines (PMID 33789347)
//   Maurer MS et al. NEJM 2018 — ATTR-ACT (tafamidis, PMID 30145929)
//   Benson MD et al. NEJM 2019 — Patisiran for hATTR (PMID 29972757)
//   Coelho T et al. NEJM 2013 — Inotersen for hATTR (PMID 23984729)
//   Kastritis E et al. NEJM 2021 — Daratumumab + VCd for AL (PMID 33951374)
//   Palladini G et al. — Mayo 2012 staging for AL amyloidosis
//   Gillmore JD et al. — Perugini score for bone scan ATTR diagnosis
// ─────────────────────────────────────────────────────────────────────────────

// ─── Types ────────────────────────────────────────────────────────────────────
export type AmyloidType =
  | "al_amyloidosis" // Light chain (plasma cell dyscrasia)
  | "attr_wt" // Wild-type ATTR (senile cardiac amyloidosis)
  | "attr_hereditary" // Hereditary ATTR (TTR mutation)
  | "aa_amyloidosis" // Serum amyloid A (chronic inflammation)
  | "unknown";

export type OrganInvolvement = {
  cardiac: boolean;
  renal: boolean;
  hepatic: boolean;
  peripheral_neuropathy: boolean;
  autonomic_neuropathy: boolean;
  gi: boolean;
  soft_tissue: boolean; // Macroglossia, periorbital purpura, carpal tunnel
};

export type ATTRMutation =
  | "val122ile" // V122I — most common in African Americans
  | "val30met" // V30M — most common hereditary ATTR worldwide
  | "thr60ala" // T60A — Irish descent
  | "other_pathogenic"
  | "none_wild_type";

export type NTproBNPStage = "stage1" | "stage2" | "stage3" | "stage3b"; // Mayo 2012 for AL
export type ALStage = "stage1" | "stage2" | "stage3" | "stage3b";

export interface AmyloidosisInput {
  // Patient profile
  age: number;
  sex: "male" | "female";
  ethnicity: "african_american" | "other"; // V122I more common in AA

  // Presenting symptoms / red flags
  symptoms: {
    heartFailure: boolean;
    unexplainedHypertrophicCM: boolean; // HCM on echo
    lowVoltageECG: boolean; // Low voltage despite LVH on echo
    bilateralCarpalTunnel: boolean;
    spinalStenosis: boolean;
    peripheralNeuropathy: boolean;
    autonomicDysfunction: boolean;
    nephrotic: boolean;
    hepatomegaly: boolean;
    macroglossia: boolean;
    periorbitalPurpura: boolean;
    unexplainedWeightLoss: boolean;
    fatigue: boolean;
  };

  // Diagnostic workup results
  hasMGUS: boolean; // Monoclonal protein on SPEP/SFLC
  hasPlasmaCellDyscrasia: boolean; // Bone marrow plasma cells >10% or myeloma
  sflcRatio: "normal" | "abnormal" | "not_done"; // Serum free light chain ratio
  boneScanResult: "grade0" | "grade1" | "grade2" | "grade3" | "not_done"; // Perugini score (Tc-PYP/DPD)
  echoLVWallThickness: number; // mm (≥12 mm = suggestive)
  echoRelativeWallThickness: "normal" | "increased"; // Concentric remodeling
  echoGLS: "normal" | "reduced" | "apical_sparing"; // Apical sparing pattern = ATTR
  ntproBNP: number; // pg/mL
  troponinT: number; // ng/L (hsTnT)
  egfr: number; // mL/min/1.73m²
  proteinuria: number; // g/24h
  ttrGeneticTest: "positive_pathogenic" | "negative" | "not_done";
  ttrMutation: ATTRMutation;
  biopsyResult: "positive_al" | "positive_attr" | "positive_aa" | "negative" | "not_done";
  biopsySite: "fat_pad" | "rectal" | "organ_biopsy" | "none";

  // Treatment context
  amyloidType: AmyloidType; // Confirmed or suspected
  ecogPS: 0 | 1 | 2 | 3 | 4;
  nyhaClass: 1 | 2 | 3 | 4;
  priorTherapy: boolean;
  patientPreference: "aggressive" | "moderate" | "bsc";
}

export type DiagnosticConfidence =
  | "confirmed" // Biopsy-proven + typing
  | "highly_likely" // Non-biopsy ATTR criteria met (bone scan + no MGUS)
  | "suspected" // Multiple red flags but incomplete workup
  | "low_suspicion";

export interface AmyloidosisResult {
  diagnosticConfidence: DiagnosticConfidence;
  suspectedType: AmyloidType;
  diagnosticLabel: string;
  diagnosticRationale: string;
  nextDiagnosticSteps: string[];
  treatmentRecommendation: string;
  treatmentRationale: string;
  stagingInfo: string;
  keyWarnings: string[];
  redFlags: string[];
  urgencyFlag: "routine" | "urgent" | "emergent";
}

// ─── Helpers ──────────────────────────────────────────────────────────────────
export function getALStage(ntproBNP: number, troponinT: number, egfr: number): ALStage {
  // Mayo 2012 staging (Dispenzieri A et al.)
  const highNT = ntproBNP >= 1800;
  const highTn = troponinT >= 25;
  const lowEGFR = egfr < 50;

  const score = [highNT, highTn, lowEGFR].filter(Boolean).length;
  if (score === 0) return "stage1";
  if (score === 1) return "stage2";
  if (score === 2) return "stage3";
  return "stage3b"; // All 3 — very high risk
}

export function getALStageLabel(stage: ALStage): string {
  const map: Record<ALStage, string> = {
    stage1: "Stage I (Median OS >5 years)",
    stage2: "Stage II (Median OS ~40 months)",
    stage3: "Stage III (Median OS ~14 months)",
    stage3b: "Stage IIIb (Median OS ~6 months) — Very High Risk",
  };
  return map[stage];
}

export function getALStageColor(stage: ALStage): string {
  const map: Record<ALStage, string> = {
    stage1: "bg-green-900/30 border-green-600/50 text-green-300",
    stage2: "bg-yellow-900/30 border-yellow-600/50 text-yellow-300",
    stage3: "bg-orange-900/30 border-orange-600/50 text-orange-300",
    stage3b: "bg-red-900/30 border-red-600/50 text-red-300",
  };
  return map[stage];
}

export function getConfidenceColor(confidence: DiagnosticConfidence): string {
  const map: Record<DiagnosticConfidence, string> = {
    confirmed: "bg-green-900/30 border-green-600/50 text-green-300",
    highly_likely: "bg-blue-900/30 border-blue-600/50 text-blue-300",
    suspected: "bg-yellow-900/30 border-yellow-600/50 text-yellow-300",
    low_suspicion: "bg-slate-800/50 border-slate-600 text-slate-400",
  };
  return map[confidence];
}

// ─── Red Flag Detection ────────────────────────────────────────────────────────
export function detectRedFlags(input: AmyloidosisInput): string[] {
  const flags: string[] = [];

  if (input.symptoms.unexplainedHypertrophicCM && input.symptoms.lowVoltageECG) {
    flags.push("CRITICAL: Hypertrophic cardiomyopathy + low-voltage ECG — classic ATTR-CM pattern. Urgent cardiac amyloidosis workup required.");
  }
  if (input.symptoms.bilateralCarpalTunnel && input.age > 60) {
    flags.push("Bilateral carpal tunnel syndrome in older adult: Soft tissue amyloid deposition — screen for ATTR.");
  }
  if (input.symptoms.spinalStenosis && input.symptoms.bilateralCarpalTunnel) {
    flags.push("Carpal tunnel + spinal stenosis: High specificity for ATTR amyloidosis. Proceed with cardiac imaging and bone scan.");
  }
  if (input.symptoms.macroglossia) {
    flags.push("Macroglossia: Highly specific for AL amyloidosis. Urgent SPEP/SFLC and bone marrow biopsy.");
  }
  if (input.symptoms.periorbitalPurpura) {
    flags.push("Periorbital purpura ('raccoon eyes'): Pathognomonic for AL amyloidosis. Urgent AL workup.");
  }
  if (input.echoLVWallThickness >= 15 && input.symptoms.heartFailure) {
    flags.push("LV wall thickness ≥15 mm with heart failure: High suspicion for cardiac amyloidosis.");
  }
  if (input.symptoms.peripheralNeuropathy && input.symptoms.autonomicDysfunction) {
    flags.push("Peripheral + autonomic neuropathy: Characteristic of hereditary ATTR (hATTR) or AL amyloidosis. Genetic testing and nerve biopsy recommended.");
  }
  if (input.symptoms.nephrotic && input.hasMGUS) {
    flags.push("Nephrotic syndrome + MGUS: High suspicion for AL amyloidosis with renal involvement. Kidney biopsy recommended.");
  }
  if (input.ethnicity === "african_american" && input.age >= 60 && input.symptoms.heartFailure) {
    flags.push("African American patient ≥60 with heart failure: V122I TTR mutation prevalence ~3–4%. Genetic testing for TTR V122I strongly recommended.");
  }

  return flags;
}

// ─── Core Logic ───────────────────────────────────────────────────────────────
export function assessAmyloidosis(input: AmyloidosisInput): AmyloidosisResult {
  const redFlags = detectRedFlags(input);
  const keyWarnings: string[] = [];
  const nextDiagnosticSteps: string[] = [];

  // ── BSC ──────────────────────────────────────────────────────────────────
  if (input.patientPreference === "bsc" || input.ecogPS === 4) {
    return {
      diagnosticConfidence: "suspected",
      suspectedType: input.amyloidType,
      diagnosticLabel: "Best Supportive Care",
      diagnosticRationale: "Patient preference or ECOG PS 4.",
      nextDiagnosticSteps: [],
      treatmentRecommendation: "Supportive care: Diuretics for heart failure, pain management, nutritional support.",
      treatmentRationale: "Goals-of-care focused management.",
      stagingInfo: "",
      keyWarnings: ["Ensure goals-of-care discussion is documented."],
      redFlags,
      urgencyFlag: "routine",
    };
  }

  // ── Confirmed AL Amyloidosis ──────────────────────────────────────────────
  if (input.amyloidType === "al_amyloidosis" || input.biopsyResult === "positive_al") {
    const alStage = getALStage(input.ntproBNP, input.troponinT, input.egfr);
    const alStageLabel = getALStageLabel(alStage);

    const isTransplantEligible =
      input.ecogPS <= 2 &&
      input.nyhaClass <= 2 &&
      input.ntproBNP < 8500 &&
      input.troponinT < 60 &&
      input.egfr >= 30;

    const treatmentRec = alStage === "stage3b"
      ? "Daratumumab + VCd (Dara-VCd) — ANDROMEDA Trial. Stage IIIb: Avoid ASCT. Dara-VCd is standard of care (Kastritis E et al., NEJM 2021, PMID 33951374). ORR 91.3%, hematologic CR 53%."
      : isTransplantEligible
      ? "Daratumumab + VCd (Dara-VCd) induction → Autologous Stem Cell Transplant (ASCT) for eligible patients. ASCT achieves highest rates of hematologic CR and organ response."
      : "Daratumumab + VCd (Dara-VCd) — ANDROMEDA regimen. Standard of care for transplant-ineligible AL amyloidosis. Dara-VCd superior to VCd alone (ANDROMEDA trial).";

    if (alStage === "stage3b") {
      keyWarnings.push("Stage IIIb AL Amyloidosis: Very poor prognosis (median OS ~6 months). Avoid cardiotoxic agents. Dara-VCd is preferred. Avoid ASCT.");
    }
    if (input.symptoms.heartFailure && input.nyhaClass >= 3) {
      keyWarnings.push("Advanced cardiac involvement (NYHA III-IV): Avoid ACE inhibitors, ARBs, beta-blockers, and calcium channel blockers — may cause severe hypotension. Use diuretics cautiously.");
    }

    return {
      diagnosticConfidence: "confirmed",
      suspectedType: "al_amyloidosis",
      diagnosticLabel: "AL Amyloidosis (Light Chain Amyloidosis)",
      diagnosticRationale: "Biopsy-proven AL amyloidosis or confirmed plasma cell dyscrasia with amyloid deposits. Congo red staining with apple-green birefringence + immunofluorescence/immunohistochemistry for light chain typing.",
      nextDiagnosticSteps: [
        "Bone marrow biopsy with plasma cell quantification and light chain restriction",
        "Echocardiogram with strain imaging (GLS, apical sparing)",
        "24-hour urine protein electrophoresis",
        "Mayo 2012 staging: NT-proBNP, hsTnT, eGFR",
        "Cardiac MRI with gadolinium (if eGFR permits)",
        "Assess ASCT eligibility: ECOG PS, NYHA class, NT-proBNP, hsTnT, eGFR",
      ],
      treatmentRecommendation: treatmentRec,
      treatmentRationale: "ANDROMEDA trial (Kastritis E et al., NEJM 2021): Daratumumab + VCd vs VCd alone — 91.3% vs 76.9% hematologic response; 53% vs 18% hematologic CR. Dara-VCd is now standard of care for newly diagnosed AL amyloidosis.",
      stagingInfo: `Mayo 2012 Stage: ${alStageLabel}`,
      keyWarnings,
      redFlags,
      urgencyFlag: alStage === "stage3b" ? "emergent" : "urgent",
    };
  }

  // ── Confirmed ATTR Amyloidosis ────────────────────────────────────────────
  if (input.amyloidType === "attr_wt" || input.amyloidType === "attr_hereditary" || input.biopsyResult === "positive_attr") {
    const isHereditary = input.amyloidType === "attr_hereditary" || input.ttrGeneticTest === "positive_pathogenic";
    const hasNeuropathy = input.symptoms.peripheralNeuropathy || input.symptoms.autonomicDysfunction;
    const hasCardiomyopathy = input.symptoms.heartFailure || input.echoLVWallThickness >= 12;

    // Non-biopsy diagnosis criteria (Gillmore 2022)
    const nonBiopsyDiagnosis =
      input.boneScanResult === "grade2" || input.boneScanResult === "grade3";
    const mgusExcluded = !input.hasMGUS && input.sflcRatio === "normal";
    const nonBiopsyATTR = nonBiopsyDiagnosis && mgusExcluded;

    const diagnosticConfidence: DiagnosticConfidence =
      input.biopsyResult === "positive_attr" ? "confirmed" :
      nonBiopsyATTR ? "highly_likely" :
      "suspected";

    let treatmentRec = "";
    let treatmentRationale = "";

    if (isHereditary && hasNeuropathy) {
      treatmentRec = "Patisiran (Onpattro) or Vutrisiran (Amvuttra) — siRNA gene silencing. First-line for hATTR polyneuropathy. Inotersen (Tegsedi) is an alternative (antisense oligonucleotide).";
      treatmentRationale = "APOLLO trial (Benson MD et al., NEJM 2019, PMID 29972757): Patisiran reduced neuropathy progression vs placebo. Vutrisiran (HELIOS-A, PMID 34126015): Non-inferior to patisiran with quarterly SC dosing. Both are FDA-approved for hATTR polyneuropathy.";
    } else if (hasCardiomyopathy) {
      treatmentRec = "Tafamidis (Vyndaqel/Vyndamax) — TTR stabilizer. Standard of care for ATTR-CM (both wt and hereditary). Acoramidis (Attruby) is an alternative TTR stabilizer approved 2024.";
      treatmentRationale = "ATTR-ACT trial (Maurer MS et al., NEJM 2018, PMID 30145929): Tafamidis reduced all-cause mortality (29.5% vs 42.9%) and CV hospitalizations vs placebo in ATTR-CM. FDA-approved for ATTR-CM (wt and hereditary). Acoramidis (ATTRibute-CM, PMID 38739481) approved 2024.";
    } else if (isHereditary) {
      treatmentRec = "Tafamidis (Vyndaqel/Vyndamax) for cardiac involvement. Patisiran or vutrisiran for neuropathy. Initiate based on predominant organ involvement.";
      treatmentRationale = "hATTR with mixed phenotype: Treat predominant organ involvement. Both TTR stabilizers and gene silencing agents are approved.";
    } else {
      treatmentRec = "Tafamidis (Vyndaqel/Vyndamax) — Standard of care for wt-ATTR cardiomyopathy.";
      treatmentRationale = "Wild-type ATTR-CM: Tafamidis is the only FDA-approved therapy. Early initiation improves outcomes.";
    }

    if (input.ttrMutation === "val122ile") {
      keyWarnings.push("V122I TTR mutation (Val122Ile): Most common hereditary ATTR in African Americans (~3–4% prevalence). Predominantly cardiac phenotype. Tafamidis is the preferred treatment.");
    }
    if (input.ttrMutation === "val30met") {
      keyWarnings.push("V30M TTR mutation (Val30Met): Most common hereditary ATTR worldwide. Predominantly neuropathic phenotype. Patisiran or vutrisiran preferred for neuropathy; tafamidis for cardiac involvement.");
    }

    return {
      diagnosticConfidence,
      suspectedType: isHereditary ? "attr_hereditary" : "attr_wt",
      diagnosticLabel: isHereditary ? "Hereditary ATTR Amyloidosis (hATTR)" : "Wild-Type ATTR Amyloidosis (wt-ATTR / Senile Cardiac Amyloidosis)",
      diagnosticRationale: nonBiopsyATTR
        ? "Non-biopsy diagnosis criteria met (Gillmore JD et al., Lancet 2022): Bone scan grade 2–3 + no MGUS/abnormal SFLC ratio. Biopsy not required for ATTR-CM diagnosis."
        : "Biopsy-proven ATTR amyloidosis with Congo red staining and mass spectrometry typing.",
      nextDiagnosticSteps: [
        ...(input.ttrGeneticTest === "not_done" ? ["TTR genetic testing (all ATTR patients) — identifies hereditary vs wt-ATTR and guides therapy selection"] : []),
        ...(input.boneScanResult === "not_done" ? ["Tc-99m PYP/DPD bone scan (Perugini score) — non-biopsy ATTR-CM diagnosis if grade 2–3 + MGUS excluded"] : []),
        "Echocardiogram with strain imaging (GLS, apical sparing pattern)",
        "Cardiac MRI with gadolinium (late gadolinium enhancement pattern)",
        "NT-proBNP and hsTnT for staging and monitoring",
        ...(isHereditary ? ["Family screening with TTR genetic testing (autosomal dominant)"] : []),
        ...(hasNeuropathy ? ["Nerve conduction studies / EMG", "Autonomic testing"] : []),
      ],
      treatmentRecommendation: treatmentRec,
      treatmentRationale,
      stagingInfo: `NYHA Class: ${input.nyhaClass} | LV Wall Thickness: ${input.echoLVWallThickness} mm | NT-proBNP: ${input.ntproBNP} pg/mL`,
      keyWarnings,
      redFlags,
      urgencyFlag: input.nyhaClass >= 3 ? "urgent" : "routine",
    };
  }

  // ── Unknown / Suspected — Diagnostic Workup ───────────────────────────────
  const redFlagCount = redFlags.length;
  const diagnosticConfidence: DiagnosticConfidence =
    redFlagCount >= 3 ? "suspected" : "low_suspicion";

  // Build diagnostic pathway
  if (input.hasMGUS || input.sflcRatio === "abnormal") {
    nextDiagnosticSteps.push("MGUS/abnormal SFLC: Prioritize AL amyloidosis workup — bone marrow biopsy, fat pad biopsy, 24-hour urine protein electrophoresis.");
  }
  if (input.symptoms.heartFailure || input.echoLVWallThickness >= 12) {
    nextDiagnosticSteps.push("Cardiac involvement suspected: Tc-99m PYP/DPD bone scan + SPEP/SFLC to differentiate ATTR vs AL.");
    nextDiagnosticSteps.push("Echocardiogram with strain imaging (apical sparing = ATTR pattern).");
    nextDiagnosticSteps.push("Cardiac MRI with gadolinium if eGFR permits.");
  }
  if (input.symptoms.peripheralNeuropathy || input.symptoms.autonomicDysfunction) {
    nextDiagnosticSteps.push("Neuropathy workup: TTR genetic testing, nerve conduction studies, autonomic testing. Consider nerve biopsy if diagnosis unclear.");
  }
  if (nextDiagnosticSteps.length === 0) {
    nextDiagnosticSteps.push("Complete amyloidosis screening: SPEP, SFLC ratio, 24-hour urine protein electrophoresis.");
    nextDiagnosticSteps.push("Echocardiogram with strain imaging.");
    nextDiagnosticSteps.push("TTR genetic testing if age >60 or African American.");
    nextDiagnosticSteps.push("Consider fat pad biopsy (sensitivity ~80% for AL, ~45% for ATTR).");
  }

  return {
    diagnosticConfidence,
    suspectedType: "unknown",
    diagnosticLabel: redFlagCount >= 3 ? "Amyloidosis Suspected — Urgent Workup Required" : "Low Suspicion — Screening Recommended",
    diagnosticRationale: redFlagCount >= 3
      ? `${redFlagCount} red flag(s) identified. Systematic amyloidosis workup is recommended to confirm or exclude diagnosis.`
      : "Insufficient features to confirm amyloidosis. Consider screening if clinical suspicion remains.",
    nextDiagnosticSteps,
    treatmentRecommendation: "Complete diagnostic workup before initiating therapy. Treatment depends on amyloid type (AL vs ATTR).",
    treatmentRationale: "Mistyping amyloid subtype leads to incorrect treatment — AL therapy (chemotherapy) is harmful in ATTR and vice versa.",
    stagingInfo: "",
    keyWarnings: [
      ...keyWarnings,
      "CRITICAL: Always type the amyloid before treating. Congo red + mass spectrometry (or immunofluorescence) is required. Treating AL as ATTR (or vice versa) can be fatal.",
    ],
    redFlags,
    urgencyFlag: redFlagCount >= 3 ? "urgent" : "routine",
  };
}
